import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

/** Total processing attempts before a job with transient failures is marked failed. */
export const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. */
export const RETRY_DELAY_MS = 500;
/** The worker counts as up if its heartbeat is at most this old. */
export const WORKER_STALE_MS = 3_000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** The public job shape returned by the API. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface JobSpec {
  input: string;
  steps: number;
  failAttempts: number;
}

export type CreateOutcome = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function nowIso(): string {
  return new Date().toISOString();
}

function one<T>(db: DatabaseSync, sql: string, ...params: Array<string | number | null>): T | undefined {
  return db.prepare(sql).get(...params) as T | undefined;
}

/** Runs `fn` inside a write transaction, so no other process can interleave with its reads and writes. */
function inTransaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction is active
    }
    throw e;
  }
  return result;
}

export function createJob(db: DatabaseSync, spec: JobSpec, idempotencyKey: string | null): CreateOutcome {
  return inTransaction(db, () => {
    if (idempotencyKey !== null) {
      const existing = one<JobRow>(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', idempotencyKey);
      if (existing) {
        const same = existing.input === spec.input && existing.steps === spec.steps && existing.fail_attempts === spec.failAttempts;
        return same ? { kind: 'replayed' as const, job: toJob(existing) } : { kind: 'conflict' as const };
      }
    }
    const now = nowIso();
    const id = randomUUID();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(id, spec.input, spec.steps, spec.failAttempts, idempotencyKey, now, now);
    const row = one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id)!;
    return { kind: 'created' as const, job: toJob(row) };
  });
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
  return row ? toJob(row) : undefined;
}

export function listJobs(db: DatabaseSync): Job[] {
  return (db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[]).map(toJob);
}

/** Worker: returns every running job to the queue, after a restart or crash. Returns how many were requeued. */
export function requeueInterruptedJobs(db: DatabaseSync): number {
  const result = db
    .prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'`)
    .run(nowIso());
  return Number(result.changes);
}

/** Worker: takes the oldest queued job that is due, marks it running and starts a new attempt. */
export function claimNextJob(db: DatabaseSync, nowMs: number): JobRow | undefined {
  return inTransaction(db, () => {
    const next = one<JobRow>(
      db,
      "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1",
      nowMs,
    );
    if (!next) return undefined;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?",
    ).run(nowIso(), next.seq);
    return one<JobRow>(db, 'SELECT * FROM jobs WHERE seq = ?', next.seq);
  });
}

export function recordProgress(db: DatabaseSync, seq: number, completed: number): void {
  db.prepare("UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE seq = ? AND status = 'running'").run(completed, nowIso(), seq);
}

export function completeJob(db: DatabaseSync, seq: number, output: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE seq = ? AND status = 'running'",
  ).run(output, nowIso(), seq);
}

export function failJob(db: DatabaseSync, seq: number, error: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, updated_at = ? WHERE seq = ? AND status = 'running'",
  ).run(error, nowIso(), seq);
}

/** Worker: puts a running job back in the queue, to be claimed again once `availableAt` (epoch ms) has passed. */
export function requeueJob(db: DatabaseSync, seq: number, availableAt: number): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ? WHERE seq = ? AND status = 'running'",
  ).run(availableAt, nowIso(), seq);
}

export function writeHeartbeat(db: DatabaseSync, name: string, nowMs: number): void {
  db.prepare('INSERT INTO heartbeats (name, seen_at) VALUES (?, ?) ON CONFLICT (name) DO UPDATE SET seen_at = excluded.seen_at').run(
    name,
    nowMs,
  );
}

/** Returns the time of the last heartbeat (epoch ms), or undefined if none has been written. */
export function readHeartbeat(db: DatabaseSync, name: string): number | undefined {
  return one<{ seen_at: number }>(db, 'SELECT seen_at FROM heartbeats WHERE name = ?', name)?.seen_at;
}

