export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | null;
}

export type ParseResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const JSON_CONTENT_TYPE = /^application\/json\s*(;.*)?$/i;

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function integerField(
  body: Record<string, unknown>,
  name: string,
  min: number,
  max: number,
  fallback: number,
  fields: FieldError[],
): number | undefined {
  const v = body[name];
  if (v === undefined) return fallback;
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
    return undefined;
  }
  return v;
}

/** Validates a `POST /api/jobs` request. Every problem found is reported, one entry per offending field. */
export function parseSubmission(
  contentType: string | undefined,
  rawBody: string,
  idempotencyKey: string | undefined,
): ParseResult {
  const fields: FieldError[] = [];
  let body: Record<string, unknown> | undefined;

  if (contentType === undefined || !JSON_CONTENT_TYPE.test(contentType.trim())) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else {
    let parsed: unknown;
    let valid = true;
    try {
      parsed = JSON.parse(rawBody);
    } catch {
      valid = false;
      fields.push({ field: 'body', message: 'Body is not valid JSON.' });
    }
    if (valid) {
      if (isPlainObject(parsed)) body = parsed;
      else fields.push({ field: 'body', message: 'Body must be a JSON object.' });
    }
  }

  let input: string | undefined;
  let steps: number | undefined;
  let failAttempts: number | undefined;
  if (body) {
    for (const key of Object.keys(body)) {
      if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
    }
    const v = body.input;
    if (typeof v !== 'string') {
      fields.push({ field: 'input', message: 'Required string.' });
    } else if (v.length < 1 || v.length > 1000) {
      fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
    } else if (v.trim() === '') {
      fields.push({ field: 'input', message: 'Must not be only whitespace.' });
    } else {
      input = v;
    }
    steps = integerField(body, 'steps', 1, 20, 5, fields);
    failAttempts = integerField(body, 'failAttempts', 0, 5, 0, fields);
  }

  let key: string | null = null;
  if (idempotencyKey !== undefined) {
    if (IDEMPOTENCY_KEY.test(idempotencyKey)) key = idempotencyKey;
    else fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  if (fields.length > 0 || input === undefined || steps === undefined || failAttempts === undefined) {
    return { ok: false, fields };
  }
  return { ok: true, value: { input, steps, failAttempts, idempotencyKey: key } };
}

