import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  completeJob,
  failJob,
  MAX_ATTEMPTS,
  recordProgress,
  requeueInterruptedJobs,
  requeueJob,
  RETRY_DELAY_MS,
  type JobRow,
  writeHeartbeat,
} from './store.ts';

/** Time for one processing step. */
const STEP_MS = 100;
/** How often an idle worker looks for queued jobs. */
const POLL_MS = 200;
/** How often the worker writes its heartbeat. */
const HEARTBEAT_MS = 1_000;

const db = openDatabase();
let stopping = false;

