import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { createJob, getJob, listJobs, readHeartbeat, WORKER_STALE_MS } from './store.ts';
import { parseSubmission, type FieldError } from './validation.ts';

/** Largest request body accepted. A 1000-character input is far smaller. */
const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

/** Reads the request body. `tooLarge` is set instead of buffering past MAX_BODY_BYTES. */
async function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    size += (chunk as Buffer).length;
    if (size > MAX_BODY_BYTES) return { text: '', tooLarge: true };
    chunks.push(chunk as Buffer);
  }
  return { text: Buffer.concat(chunks).toString('utf8'), tooLarge: false };
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const parsed = tooLarge
    ? { ok: false as const, fields: [{ field: 'body', message: 'Body is too large.' }] }
    : parseSubmission(req.headers['content-type'], text, req.headers['idempotency-key']);
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', parsed.fields);
    return;
  }
  const { idempotencyKey, ...spec } = parsed.value;
  const outcome = createJob(db, spec, idempotencyKey);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

function handleHealth(res: ServerResponse): void {
  const seen = readHeartbeat(db, 'worker');
  const up = seen !== undefined && Date.now() - seen <= WORKER_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function jobIdFromPath(pathname: string): string | undefined {
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (!match) return undefined;
  try {
    return decodeURIComponent(match[1]!);
  } catch {
    return '';
  }
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const notAllowed = () => sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);

  if (pathname === '/health') {
    return method === 'GET' ? handleHealth(res) : notAllowed();
  }
  if (pathname === '/') {
    if (method !== 'GET') return notAllowed();
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: listJobs(db) });
    if (method === 'POST') return handleCreate(req, res);
    return notAllowed();
  }
  const id = jobIdFromPath(pathname);
  if (id !== undefined) {
    if (method !== 'GET') return notAllowed();
    const job = id === '' ? undefined : getJob(db, id);
    if (!job) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, job);
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e instanceof Error ? e.message : e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.closeAllConnections();
  server.close(() => {
    db.close();
    console.log('server stopped');
    process.exit(0);
  });
  // Do not hang on connections that never finish.
  setTimeout(() => process.exit(0), 3_000).unref();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

