const dir = mkdtempSync(join(process.env.TMPDIR || tmpdir(), 'jt-'));
const DB = join(dir, 'sub', 'jobs.db');
const PORT = 3917;
const base = `http://127.0.0.1:${PORT}`;
const env = { ...process.env, PORT: String(PORT), DATABASE_PATH: DB };
let failures = 0;
const check = (name, cond, extra = '') => { console.log(`${cond ? 'PASS' : 'FAIL'} ${name} ${cond ? '' : JSON.stringify(extra)}`); if (!cond) failures++; };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function start(which) {
  const p = spawn('node', ['--disable-warning=ExperimentalWarning', join(ROOT, 'dist', `${which}.js`)], { env, stdio: ['ignore', 'pipe', 'pipe'] });
  p.stdout.on('data', (d) => process.stdout.write(`[${which}] ${d}`));
  p.stderr.on('data', (d) => process.stdout.write(`[${which} ERR] ${d}`));
  return p;
}
const exited = (p) => new Promise((r) => p.once('exit', (code, sig) => r({ code, sig })));
async function post(body, headers = {}, raw) {
  const r = await fetch(`${base}/api/jobs`, { method: 'POST', headers: { 'content-type': 'application/json', ...headers }, body: raw ?? JSON.stringify(body) });
  return { status: r.status, json: await r.json().catch(() => null), ct: r.headers.get('content-type') };
}
const get = async (p) => { const r = await fetch(base + p); return { status: r.status, json: await r.json().catch(() => null), text: null }; };
async function waitStatus(id, want, ms = 15000) {
  const end = Date.now() + ms; let j;
  while (Date.now() < end) { j = (await get(`/api/jobs/${id}`)).json; if (want.includes(j.status)) return j; await sleep(100); }
  return j;
}

let server = start('server');
let worker = start('worker');
await sleep(1500);
const h = await get('/health');
check('health ok', h.status === 200 && h.json.status === 'ok' && h.json.worker === 'up', h);

// Validation
const bad = [
  [{ input: '' }, 'input'], [{ input: '   ' }, 'input'], [{}, 'input'], [{ input: 'a'.repeat(1001) }, 'input'],
  [{ input: 'a', steps: 0 }, 'steps'], [{ input: 'a', steps: 21 }, 'steps'], [{ input: 'a', steps: 2.5 }, 'steps'], [{ input: 'a', steps: '3' }, 'steps'],
  [{ input: 'a', failAttempts: 6 }, 'failAttempts'], [{ input: 'a', failAttempts: null }, 'failAttempts'], [{ input: 'a', extra: 1 }, 'extra'],
  [[1, 2], 'body'], ['str', 'body'], [null, 'body'],
];
