const lat = [];
for (let i = 0; i < 5; i++) {
  const t0 = Date.now();
  const r = await fetch(`http://127.0.0.1:${PORT}/api/jobs`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ input: 'x', steps: 1 }) });
  const job = await r.json();
