  let running = 0;
  while (true) {
    const j = await (await fetch(`http://127.0.0.1:${PORT}/api/jobs/${job.id}`)).json();
    if (j.status !== 'queued') { running = Date.now() - t0; break; }
    await sleep(20);
  }
  lat.push({ postMs: post, pickupMs: running });
  await sleep(300);
}
console.log(JSON.stringify(lat));
s.kill('SIGTERM'); w.kill('SIGTERM');
